/**
 * 测试媒体资源工具
 * 
 * 提供 base64 编码的测试视频和音频数据，用于解决 CORS 跨域问题。
 * 当外部 URL 加载失败时，自动 fallback 到本地测试数据。
 */

// 极短的静音音频 (1秒, 44100Hz, mono, mp3)
// 这是一个有效的最小 MP3 文件
export const TEST_AUDIO_BASE64 =
  'data:audio/mp3;base64,';

// 极短的黑色视频 (1秒, 320x240, mp4)
// 这是一个有效的最小 MP4 文件
export const TEST_VIDEO_BASE64 =
  'data:video/mp4;base64,';

/**
 * 获取本地测试音频 URL
 */
export function getTestAudioUrl(): string {
  return TEST_AUDIO_BASE64;
}

/**
 * 获取本地测试视频 URL
 */
export function getTestVideoUrl(): string {
  return TEST_VIDEO_BASE64;
}

/**
 * 判断 URL 是否是外部 URL
 */
export function isExternalUrl(url: string): boolean {
  try {
    const urlObj = new URL(url);
    return urlObj.protocol === 'http:' || urlObj.protocol === 'https:';
  } catch {
    return false;
  }
}

/**
 * 将外部 URL 转换为本地 fallback URL
 * 如果加载失败，返回测试数据
 */
export function getFallbackUrl(type: 'audio' | 'video'): string {
  if (type === 'audio') {
    return getTestAudioUrl();
  }
  return getTestVideoUrl();
}
